  justify-content: center;
  align-items: center;
`;

let Logo = styled.span`
  height: 46px;
  padding: 0px 5px;
  display: flex;
  color: black;
  background: rgba(255, 255, 255, 0.85);
  font-weight: 600;
  font-size: 0.9em;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;

  // Triangle on the left
  &::before {
    content: '';
