  return (
    <Wrapper
      initial={{ y: -100, scale: 0.6 }}
      animate={y < 300 ? { y: -100, scale: 1 } : { y: 0, scale: 1 }}
      transition={{ type: 'spring', stiffness: 100, damping: 15 }}
    >
